using System;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// A four-sided panel cut from a surface. Immutable: every derived value is computed once on construction.
    /// </summary>
    public sealed class FacadePanel
    {
        private const double Degenerate = 1e-12;

        public FacadePanel(int index, Point3d[] corners)
        {
            if (corners == null || corners.Length != 4)
                throw new ArgumentException("A panel needs exactly four corners.", nameof(corners));

            Index = index;
            Corners = (Point3d[])corners.Clone();

            Point3d c0 = Corners[0], c1 = Corners[1], c2 = Corners[2], c3 = Corners[3];

            Outline = new PolylineCurve(new[] { c0, c1, c2, c3, c0 });
            Center = new Point3d(
                (c0.X + c1.X + c2.X + c3.X) / 4.0,
                (c0.Y + c1.Y + c2.Y + c3.Y) / 4.0,
                (c0.Z + c1.Z + c2.Z + c3.Z) / 4.0);

            // Area of the two triangles that split the quad; well defined even when the panel is not planar.
            Area = TriangleArea(c0, c1, c2) + TriangleArea(c0, c2, c3);

            // Distance from the fourth corner to the plane through the other three.
            Deviation = DistanceToPlane(c3, c0, c1, c2);

            EdgeLengths = new[] { c0.DistanceTo(c1), c1.DistanceTo(c2), c2.DistanceTo(c3), c3.DistanceTo(c0) };
            Diagonals = new[] { c0.DistanceTo(c2), c1.DistanceTo(c3) };

            SortedEdges = (double[])EdgeLengths.Clone();
            Array.Sort(SortedEdges);
            SortedDiagonals = (double[])Diagonals.Clone();
            Array.Sort(SortedDiagonals);

            // Rectangle used for nesting: mean of opposite edges.
            Width = (EdgeLengths[0] + EdgeLengths[2]) / 2.0;
            Height = (EdgeLengths[1] + EdgeLengths[3]) / 2.0;
        }

        /// <summary>Position in the grid (row-major: V row times U count plus U column).</summary>
        public int Index { get; }

        /// <summary>Four corners in order around the panel. Do not modify the array.</summary>
        public Point3d[] Corners { get; }

        /// <summary>Closed polyline through the four corners.</summary>
        public PolylineCurve Outline { get; }

        public double Area { get; }

        public Point3d Center { get; }

        /// <summary>Distance from corner 3 to the plane through corners 0, 1 and 2.</summary>
        public double Deviation { get; }

        /// <summary>Edge lengths in order: edge 0-1, 1-2, 2-3, 3-0.</summary>
        public double[] EdgeLengths { get; }

        /// <summary>Diagonal lengths: 0-2 and 1-3.</summary>
        public double[] Diagonals { get; }

        /// <summary>Rectangle width used for nesting and the cut list: mean of edges 0-1 and 2-3.</summary>
        public double Width { get; }

        /// <summary>Rectangle height used for nesting and the cut list: mean of edges 1-2 and 3-0.</summary>
        public double Height { get; }

        private readonly double[] SortedEdges;
        private readonly double[] SortedDiagonals;

        /// <summary>
        /// Two panels are identical when their sorted edge lengths and their sorted diagonal lengths
        /// each differ by at most <paramref name="tolerance"/>.
        /// </summary>
        public bool IsIdenticalTo(FacadePanel other, double tolerance)
        {
            if (other == null) return false;
            for (int i = 0; i < SortedEdges.Length; i++)
                if (Math.Abs(SortedEdges[i] - other.SortedEdges[i]) > tolerance) return false;
            for (int i = 0; i < SortedDiagonals.Length; i++)
                if (Math.Abs(SortedDiagonals[i] - other.SortedDiagonals[i]) > tolerance) return false;
            return true;
        }

        private static double TriangleArea(Point3d a, Point3d b, Point3d c)
        {
            return 0.5 * Vector3d.CrossProduct(b - a, c - a).Length;
        }

        private static double DistanceToPlane(Point3d p, Point3d a, Point3d b, Point3d c)
        {
            Vector3d n = Vector3d.CrossProduct(b - a, c - a);
            double len = n.Length;
            // Collinear reference points define no plane; treat the panel as flat in that case.
            if (len < Degenerate) return 0.0;
            Vector3d v = p - a;
            return Math.Abs(v.X * n.X + v.Y * n.Y + v.Z * n.Z) / len;
        }
    }
}

