using System.Collections.Generic;

namespace BenchPlugin.Facade
{
    /// <summary>Conversions between panel wire items and plain panel lists.</summary>
    public static class PanelData
    {
        /// <summary>Returns the panels inside the wrappers, or null if any item is empty.</summary>
        public static List<FacadePanel> ValuesOf(IEnumerable<PanelGoo> goos)
        {
            var panels = new List<FacadePanel>();
            foreach (PanelGoo goo in goos)
            {
                if (goo == null || goo.Value == null) return null;
                panels.Add(goo.Value);
            }
            return panels;
        }

        public static List<PanelGoo> Wrap(IEnumerable<FacadePanel> panels)
        {
            var goos = new List<PanelGoo>();
            foreach (FacadePanel panel in panels) goos.Add(new PanelGoo(panel));
            return goos;
        }
    }
}

