using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade
{
    /// <summary>A rectangle placed on a sheet. X and Y are the bottom-left corner on that sheet.</summary>
    public sealed class PlacedPart
    {
        public PlacedPart(int part, int sheet, double x, double y, double width, double height)
        {
            Part = part;
            Sheet = sheet;
            X = x;
            Y = y;
            Width = width;
            Height = height;
        }

        /// <summary>Index into the input arrays.</summary>
        public int Part { get; }
        public int Sheet { get; }
        public double X { get; }
        public double Y { get; }
        /// <summary>Width after any 90 degree turn.</summary>
        public double Width { get; }
        /// <summary>Height after any 90 degree turn.</summary>
        public double Height { get; }
    }

    public sealed class NestResult
    {
        public NestResult(List<PlacedPart> placed, int sheetCount, int unplaced, double utilization)
        {
            Placed = placed;
            SheetCount = sheetCount;
            Unplaced = unplaced;
            Utilization = utilization;
        }

        public IReadOnlyList<PlacedPart> Placed { get; }
        public int SheetCount { get; }
