using System;
using System.Threading;
using System.Threading.Tasks;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One background nesting run for a fixed set of inputs. The component keeps the latest run,
    /// cancels it when the inputs change, and polls <see cref="Progress"/> until <see cref="Finished"/>.
    /// </summary>
    public sealed class NestRun
    {
        private readonly CancellationTokenSource _cts = new CancellationTokenSource();

        private volatile double _progress;
        private volatile bool _finished;
        private volatile bool _cancelled;

        public NestRun(double[] signature, double[] widths, double[] heights, double sheetWidth, double sheetHeight, double spacing)
        {
            Signature = signature;
            Task.Run(() => Execute(widths, heights, sheetWidth, sheetHeight, spacing));
        }

        /// <summary>The inputs this run was started with.</summary>
        public double[] Signature { get; }

        /// <summary>Fraction of parts processed, 0 to 1.</summary>
        public double Progress => _progress;

        public bool Finished => _finished;

        public bool Cancelled => _cancelled;

        public NestResult Result { get; private set; }

        public Exception Error { get; private set; }

        public void Cancel() => _cts.Cancel();

        private void Execute(double[] widths, double[] heights, double sheetWidth, double sheetHeight, double spacing)
        {
            try
            {
                Result = ShelfNester.Run(widths, heights, sheetWidth, sheetHeight, spacing,
                    p => _progress = p, _cts.Token);
            }
            catch (OperationCanceledException)
            {
                _cancelled = true;
            }
            catch (Exception ex)
            {
                Error = ex;
            }
            finally
            {
                // Volatile write: Result and Error are visible to any thread that sees Finished.
                _finished = true;
            }
        }
    }
}

