using System;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Components
{
    public class PanelizeSurfaceComponent : GH_Component
    {
        public PanelizeSurfaceComponent()
            : base("Panelize Surface", "Panelize", "Divides a surface into a grid of four-sided facade panels", "Facade", "Panels")
        {
        }

        public override Guid ComponentGuid => new Guid("6f2a9c41-0d3b-4e7a-9b15-2c8d4e6f1a03");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddSurfaceParameter("Surface", "S", "Surface to divide into panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("U Count", "U", "Number of panels along U", GH_ParamAccess.item, 10);
            pManager.AddIntegerParameter("V Count", "V", "Number of panels along V", GH_ParamAccess.item, 6);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "One panel per grid cell", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outlines", "O", "Closed outline of each panel", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Surface surface = null;
            int uCount = 0, vCount = 0;
            if (!DA.GetData(0, ref surface)) return;
            if (!DA.GetData(1, ref uCount)) return;
            if (!DA.GetData(2, ref vCount)) return;

            if (uCount < 1 || vCount < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "U Count and V Count must both be at least 1.");
                return;
            }

            Interval uDomain = surface.Domain(0);
            Interval vDomain = surface.Domain(1);

            // Evaluate each grid vertex once; neighbouring panels share vertices.
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
            {
                double u = uDomain.T0 + uDomain.Length * i / uCount;
                for (int j = 0; j <= vCount; j++)
                {
                    double v = vDomain.T0 + vDomain.Length * j / vCount;
                    grid[i, j] = surface.PointAt(u, v);
                }
            }

            var panels = new List<FacadePanel>(uCount * vCount);
            var outlines = new List<Curve>(uCount * vCount);
            for (int j = 0; j < vCount; j++)
            {
                for (int i = 0; i < uCount; i++)
                {
                    // Corners in order around the cell: (u0,v0), (u1,v0), (u1,v1), (u0,v1).
                    var corners = new[] { grid[i, j], grid[i + 1, j], grid[i + 1, j + 1], grid[i, j + 1] };
                    var panel = new FacadePanel(j * uCount + i, corners);
                    panels.Add(panel);
                    outlines.Add(panel.Outline.DuplicateCurve());
                }
            }

            DA.SetDataList(0, PanelData.Wrap(panels));
            DA.SetDataList(1, outlines);
        }
    }
}

