using System;
using System.Collections.Generic;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class PlanarityComponent : GH_Component
    {
        public PlanarityComponent()
            : base("Planarity", "Planarity", "Measures how far each panel is from planar", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("9c4d1e67-2f5a-4b8e-8d30-7a1f6e2c5b25");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels to check", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Largest deviation still counted as flat", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Deviation", "D", "Distance from the fourth corner to the plane of the other three", GH_ParamAccess.list);
            pManager.AddBooleanParameter("Flat", "F", "True when the deviation is at most the tolerance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var goos = new List<PanelGoo>();
            double tolerance = 0.5;
            if (!DA.GetDataList(0, goos)) return;
            if (!DA.GetData(1, ref tolerance)) return;

            var panels = PanelData.ValuesOf(goos);
            if (panels == null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "The Panels input contains an empty item.");
                return;
            }

            var deviations = new List<double>(panels.Count);
            var flats = new List<bool>(panels.Count);
            int flatCount = 0;
            foreach (FacadePanel panel in panels)
            {
                deviations.Add(panel.Deviation);
                bool flat = panel.Deviation <= tolerance;
                flats.Add(flat);
                if (flat) flatCount++;
            }

            int notFlat = panels.Count - flatCount;
            if (notFlat * 2 > panels.Count)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{notFlat} of {panels.Count} panels are not flat (deviation above {tolerance}).");
            }

            DA.SetDataList(0, deviations);
            DA.SetDataList(1, flats);
            DA.SetData(2, flatCount);
        }
    }
}

