using System;
using System.Collections.Generic;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class PanelStatsComponent : GH_Component
    {
        public PanelStatsComponent()
            : base("Panel Stats", "Panel Stats", "Total, minimum, maximum and mean panel area", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("5a1c7d83-9e4f-4a26-9d72-4b3e8f0a2c47");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels to measure", GH_ParamAccess.list);
            // Optional so that an empty input reaches SolveInstance and can report the error.
            pManager[0].Optional = true;
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Total Area", "Σ", "Sum of all panel areas", GH_ParamAccess.item);
            pManager.AddNumberParameter("Min Area", "Min", "Smallest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Max Area", "Max", "Largest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Mean Area", "Mean", "Average panel area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var goos = new List<PanelGoo>();
            if (!DA.GetDataList(0, goos)) return;

            var panels = PanelData.ValuesOf(goos);
            if (panels == null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "The Panels input contains an empty item.");
                return;
            }
            if (panels.Count == 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "No panels to measure.");
                return;
            }

            double total = 0.0, min = double.MaxValue, max = double.MinValue;
            foreach (FacadePanel panel in panels)
            {
                double area = panel.Area;
