using System;
using System.Collections.Generic;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group Panels", "Groups panels whose edge and diagonal lengths match within a tolerance", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("c7f2b946-1a8e-4d35-8f6c-9e0b2d4a7158");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels to group", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Largest allowed difference in any sorted edge or diagonal length", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number of each panel, numbered from 0 in order of first appearance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParam(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var goos = new List<PanelGoo>();
            double tolerance = 1.0;
            if (!DA.GetDataList(0, goos)) return;
            if (!DA.GetData(1, ref tolerance)) return;

            var panels = PanelData.ValuesOf(goos);
            if (panels == null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "The Panels input contains an empty item.");
                return;
            }

            var representatives = new List<FacadePanel>();
            var groups = new List<int>(panels.Count);
            foreach (FacadePanel panel in panels)
            {
                int found = -1;
                for (int g = 0; g < representatives.Count; g++)
                {
                    if (panel.IsIdenticalTo(representatives[g], tolerance))
                    {
                        found = g;
                        break;
                    }
                }
                if (found < 0)
                {
                    representatives.Add(panel);
                    found = representatives.Count - 1;
                }
                groups.Add(found);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, representatives.Count);
            DA.SetDataList(2, PanelData.Wrap(representatives));
        }
    }
}

