using System;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Components
{
    public class NestOnSheetsComponent : GH_Component
    {
        /// <summary>Gap between neighbouring sheets in the output, in addition to the sheet width.</summary>
        private const double SheetGap = 100.0;

        /// <summary>How often a running nest asks Grasshopper to refresh, to show progress.</summary>
        private const int PollMilliseconds = 250;

        private NestRun _run;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Nests panel rectangles on sheets with a shelf algorithm", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("2d9e6a14-7c3b-4f82-a5e1-8b6c0f3d9e69");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels to nest", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "W", "Width of each sheet", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Height of each sheet", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Rectangle of each placed panel, sheets side by side along X", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index of each placed panel, in the same order as Outlines", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed area divided by the area of all sheets used", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var goos = new List<PanelGoo>();
            double sheetWidth = 0, sheetHeight = 0, spacing = 0;
            if (!DA.GetDataList(0, goos)) return;
            if (!DA.GetData(1, ref sheetWidth)) return;
            if (!DA.GetData(2, ref sheetHeight)) return;
            if (!DA.GetData(3, ref spacing)) return;

            if (sheetWidth <= 0 || sheetHeight <= 0 || spacing < 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Sheet Width and Sheet Height must be positive, and Spacing cannot be negative.");
                return;
            }

            var panels = PanelData.ValuesOf(goos);
            if (panels == null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "The Panels input contains an empty item.");
                return;
            }

            var widths = new double[panels.Count];
            var heights = new double[panels.Count];
            for (int i = 0; i < panels.Count; i++)
            {
                widths[i] = panels[i].Width;
                heights[i] = panels[i].Height;
            }

            double[] signature = BuildSignature(widths, heights, sheetWidth, sheetHeight, spacing);
            if (_run == null || !SameSignature(_run.Signature, signature))
            {
                // Inputs changed: stop the previous run and start over.
                _run?.Cancel();
                _run = new NestRun(signature, widths, heights, sheetWidth, sheetHeight, spacing);
            }

            if (!_run.Finished)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Remark, $"Nesting... {(int)Math.Round(_run.Progress * 100)}%");
                ScheduleRefresh();
                return;
            }

            if (_run.Error != null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Nesting failed: " + _run.Error.Message);
                return;
            }

            if (_run.Cancelled || _run.Result == null) return;

            PublishResult(DA, _run.Result, sheetWidth);
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            _run?.Cancel();
            base.RemovedFromDocument(document);
        }

        private void PublishResult(IGH_DataAccess DA, NestResult result, double sheetWidth)
        {
            double sheetPitch = sheetWidth + SheetGap;
            var outlines = new List<Curve>(result.Placed.Count);
            var sheets = new List<int>(result.Placed.Count);

            foreach (PlacedPart part in result.Placed)
            {
                double x0 = part.Sheet * sheetPitch + part.X;
                double y0 = part.Y;
                double x1 = x0 + part.Width;
                double y1 = y0 + part.Height;

                var rect = new PolylineCurve(new[]
                {
                    new Point3d(x0, y0, 0), new Point3d(x1, y0, 0),
                    new Point3d(x1, y1, 0), new Point3d(x0, y1, 0),
                    new Point3d(x0, y0, 0)
                });
                outlines.Add(rect);
                sheets.Add(part.Sheet);
            }

            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, result.SheetCount);
            DA.SetData(3, result.Utilization);

            if (result.Unplaced > 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{result.Unplaced} panel(s) fit on no sheet and were left out.");
            }
        }

        /// <summary>Asks Grasshopper to solve again shortly, so a running nest shows fresh progress and its result gets published.</summary>
        private void ScheduleRefresh()
        {
            GH_Document doc = OnPingDocument();
            doc?.ScheduleSolution(PollMilliseconds, d => ExpireSolution(true));
        }

        private static double[] BuildSignature(double[] widths, double[] heights, double sheetWidth, double sheetHeight, double spacing)
        {
            var signature = new double[widths.Length * 2 + 3];
            Array.Copy(widths, 0, signature, 0, widths.Length);
            Array.Copy(heights, 0, signature, widths.Length, heights.Length);
            signature[signature.Length - 3] = sheetWidth;
            signature[signature.Length - 2] = sheetHeight;
            signature[signature.Length - 1] = spacing;
            return signature;
        }

        private static bool SameSignature(double[] a, double[] b)
        {
            if (a.Length != b.Length) return false;
            for (int i = 0; i < a.Length; i++)
                if (a[i] != b[i]) return false;
            return true;
        }
    }
}

