using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class CutListComponent : GH_Component
    {
        private const string Header = "index,width,height,area,deviation";
        private const string Format = "0.###";

        public CutListComponent()
            : base("Cut List", "Cut List", "Builds a CSV cut list of panels and optionally writes it to a file", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("e4b8c270-5d1f-4a6e-9c39-6f2a7b1e0d7a");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels to list", GH_ParamAccess.list);
            pManager.AddTextParameter("Path", "Path", "File to write the CSV to (used only when Write is true)", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Write", "W", "Write the CSV to Path", GH_ParamAccess.item, false);
            pManager[1].Optional = true;
            pManager[2].Optional = true;
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Header line and one line per panel", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "OK", "True when the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var goos = new List<PanelGoo>();
            string path = string.Empty;
            bool write = false;
            if (!DA.GetDataList(0, goos)) return;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            var panels = PanelData.ValuesOf(goos);
            if (panels == null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "The Panels input contains an empty item.");
                return;
            }

            var sb = new StringBuilder();
            sb.AppendLine(Header);
            foreach (FacadePanel panel in panels)
            {
                sb.AppendLine(string.Join(",",
                    panel.Index.ToString(CultureInfo.InvariantCulture),
                    panel.Width.ToString(Format, CultureInfo.InvariantCulture),
                    panel.Height.ToString(Format, CultureInfo.InvariantCulture),
                    panel.Area.ToString(Format, CultureInfo.InvariantCulture),
                    panel.Deviation.ToString(Format, CultureInfo.InvariantCulture)));
            }
            string csv = sb.ToString();

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                {
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty. The CSV was not written.");
                }
                else
                {
                    try
                    {
                        File.WriteAllText(path, csv);
                        written = true;
                    }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write the CSV: " + ex.Message);
                    }
                }
            }

            DA.SetData(0, csv);
            DA.SetData(1, written);
        }
    }
}

